mapper.sql:
where 1=1

		and cdrg_llave = #{llaveTabla}


		and cdrg_estado = #{estado}


		and cdrg_documentoprincipal = #{documentoPrincipal}


		and cdrg_documentomodificador = #{documentoModificador}


		and ddrg_fecha >= #{fechaMin}


		and ddrg_fecha  <   #{fechaMax}


		and cdrg_estadoinicial = #{estadoInicial}


		and cdrg_estadofinal = #{estadoFinal}


		and cdrg_usuario = #{usuario}


		and cdrg_valores = #{valores}


		and cdrg_transaccion = #{transaccion}


		and ddrg_cierre >= #{cierreMin}


		and ddrg_cierre  <   #{cierreMax}


		and cdrg_nombre = #{nombre}


		and bdrg_estadorepetido = #{estadorepetidoFilter}

mapper.select:
select cdrg_llave as llaveTabla ,cdrg_documentoprincipal as documentoPrincipal ,cdrg_documentomodificador as documentoModificador ,ddrg_fecha as fecha ,(select cpes_nombre from procesoestado_pesp where cpes_llave = cdrg_estadoinicial) as estadoInicial ,(select cpes_nombre from procesoestado_pesp where cpes_llave = cdrg_estadofinal) as estadoFinal ,'TRAZA' as estado ,cdrg_usuario as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = cdrg_usuario) as responsable ,(select cusr_imagen from usuario_usrp where cusr_llave = cdrg_usuario) as responsableImagen ,modifica.cpdv_nombre as modificadorNombre ,descripcion(modifica.cpdv_llave) as comentario ,modifica.cpdv_plantilla as plantilla ,(select cdpl_nombre from documentoplantilla_dplp where cdpl_llave = modifica.cpdv_plantilla) as plantillaNombre ,cdrg_nombre as nombre ,cdrg_transaccion as transaccion ,(select cpvc_valortext from campo4id ( cdrg_documentomodificador , (select cppd_valor from propiedad_ppdp where cppd_propiedadvalor = 'PROP_178' and cppd_estado = 'A' and cppd_tipo = 'L' and cppd_campo = (select cpdv_plantilla from pedidoventa_pdvp where cpdv_llave = cdrg_documentomodificador)), modifica.npdv_historico)) as adjunto from documentorelaciongestor_drgphistoric.z_drg_documentorelaciongestor left join pedidoventa_pdvp modifica on (cpdv_llave = cdrg_documentomodificador) where cdrg_documentoprincipal = #{dto.documentoPrincipal}
union select cact_llave as llaveTabla ,cact_llave as documentoPrincipal ,null as documentoModificador ,dact_fecharegistro as fecha ,null as estadoInicial ,null as estadoFinal ,'ASIGNACION' as estado ,cact_usuarioregistro as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = cact_usuarioregistro) as responsable ,(select cusr_imagen from usuario_usrp where cusr_llave = cact_usuarioregistro) as responsableImagen ,null as modificadorNombre ,cact_comentario as comentario ,null as plantilla ,null as plantillaNombre ,(select 'Asignado a ' || cusr_nombre from usuario_usrp where cusr_llave = cact_responsable) as nombre ,null as transaccion ,null as adjunto from actividad_actp where cact_documento = #{dto.documentoPrincipal} union select cpva_llave as llaveTabla ,cpva_llave as documentoPrincipal ,null as documentoModificador ,dpva_fecha as fecha ,(select cpes_nombre from procesoestado_pesp where cpes_llave = cpva_estadoinicial) as estadoInicial ,(select cpes_nombre from procesoestado_pesp where cpes_llave = cpva_estadofinal) as estadoFinal ,'ASIGNACION' as estado ,cpva_responsable as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = cpva_responsable) as responsable ,(select cusr_imagen from usuario_usrp where cusr_llave = cpva_responsable) as responsableImagen ,null as modificadorNombre ,cpva_motivo as comentario ,null as plantilla ,null as plantillaNombre ,null as nombre ,null as transaccion ,null as adjunto from pedidoventaajuste_pvap where cpva_documento = #{dto.documentoPrincipal}
union select cmsj_llave as llaveTabla ,cmsj_documento as documentoPrincipal ,null as documentoModificador ,dmsj_fecha as fecha ,null as estadoInicial ,null as estadoFinal ,'MENSAJE' as estado ,null as usuario ,null as responsable ,null as responsableImagen ,null as modificadorNombre ,case when cmsj_correoerror is null then 'Titulo: ' || cmsj_titulo else 'Error: ' || cmsj_correoerror end as comentario ,null as plantilla ,null as plantillaNombre ,case when dmsj_correoenviado is null then 'Mensaje sin correo enviado al destinatario ' || cmsj_correo else CASE WHEN cmsj_correoerror is null THEN 'Mensaje enviado el ' || to_char(dmsj_correoenviado, 'yyyy-mm-dd HH24:MI:SS') || ' a ' || cmsj_correo ELSE 'Error al enviar mensaje a ' || cmsj_correo || ', enviado el ' || to_char(dmsj_correoenviado, 'yyyy-mm-dd HH24:MI:SS') END END as nombre ,null as transaccion ,cmsj_adjuntourl as adjunto from mensaje_msjp where cmsj_documento = #{dto.documentoPrincipal}
union select ctpi_llave as llaveTabla ,cdpr_documento as documentoPrincipal ,cpro_documento as documentoModificador ,dtpi_fecha as fecha ,descripcion(ctpi_bodega) as estadoInicial ,null as estadoFinal ,'INVENTARIO' as estado ,ctpi_responsable as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = ctpi_responsable) as responsable ,(select cusr_imagen from usuario_usrp where cusr_llave = ctpi_responsable) as responsableImagen ,null as modificadorNombre ,('[ Inician : ' || mtpi_cantidadinicial || '] Se mueve inventario de: ' || mtpi_cantidad || ' => Terminan : ' || mtpi_cantidadfinal) as comentario ,cpdv_plantilla as plantilla ,null as plantillaNombre ,descripcion(cpro_documento) as nombre ,null as transaccion ,null as adjunto from trazabilidadproductoinventario_tpip inner join deduccionproducto_dprp on (cdpr_llave = ctpi_deduccionproducto ) inner join producto_prop on (cpro_llave = ctpi_producto) inner join pedidoventa_pdvp on (cpdv_llave = cpro_documento) where cdpr_documento = #{dto.documentoPrincipal}
union select cwse_llave as llaveTabla ,cwse_documento as documentoPrincipal ,null as documentoModificador ,case when dwse_fechaejecucion is not null then dwse_fechaejecucion else dwse_fecha end as fecha ,cwse_entrada as estadoInicial ,cwse_salida as estadoFinal ,'API' as estado ,cwse_usuario as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = cwse_usuario) as responsable ,null as responsableImagen ,null as modificadorNombre ,cwse_error as comentario ,null as plantilla ,null as plantillaNombre ,(select cwbs_nombre from webservice_wbsp where cwbs_llave = cwse_servicio) as nombre ,null as transaccion ,cwse_masivo as adjunto from webserviceejecucion_wsep where cwse_documento = #{dto.documentoPrincipal} and cwse_estado = 'A'
union select crej_llave as llaveTabla ,crej_documento as documentoPrincipal ,null as documentoModificador ,drej_fechainicio as fecha ,'Impresion de reporte' as estadoInicial ,(drej_fechafin - drej_fechainicio)::text as estadoFinal ,'REPORTES' as estado ,crej_usuario as usuario ,(select cusr_nombre from usuario_usrp where cusr_llave = crej_usuario) as responsable ,null as responsableImagen ,null as modificadorNombre ,crej_error as comentario ,null as plantilla ,null as plantillaNombre ,(select crpb_nombre from reportebase_rpbp where crpb_llave = crej_reporte) as nombre ,null as transaccion ,crej_url as adjunto from reporteejecucion_rejphistoric.z_rej_reporteejecucion where crej_documento = #{dto.documentoPrincipal}
union select cpvd_llave as llaveTabla ,cpvd_documento as documentoPrincipal ,null as documentoModificador ,dpvd_fecha as fecha ,TO_CHAR(mpvd_saldo, 'FM999999999.##') as estadoInicial ,TO_CHAR(mpvd_valortotal, 'FM999999999.##') as estadoFinal ,'VALORES' as estado ,null as usuario ,null as responsable ,null as responsableImagen ,null as modificadorNombre ,null as comentario ,null as plantilla ,null as plantillaNombre ,null as nombre ,null as transaccion ,null as adjunto from pedidoventadinero_pvdphistoric.z_pvd_pedidoventadinero where cpvd_documento = #{dto.documentoPrincipal}
union select cpvu_llave as llaveTabla ,cpvu_documento as documentoPrincipal ,cpvu_ubicacion as documentoModificador ,dpvu_fecha as fecha ,null as estadoInicial ,null as estadoFinal ,'UBICACION' as estado ,null as usuario ,null as responsable ,null as responsableImagen ,modifica.cpdv_nombre as modificadorNombre ,descripcion(modifica.cpdv_llave) as comentario ,modifica.cpdv_plantilla as plantilla ,(select cdpl_nombre from documentoplantilla_dplp where cdpl_llave = modifica.cpdv_plantilla) as plantillaNombre ,null as nombre ,null as transaccion ,null as adjunto from pedidoventaubicacion_pvuphistoric.z_pvu_pedidoventaubicacion inner join pedidoventa_pdvp modifica on (cpdv_llave = cpvu_ubicacion) where cpvu_documento = #{dto.documentoPrincipal}
union select ccmp_llave as llaveTabla ,ccmp_documento as documentoPrincipal ,null as documentoModificador ,cc.dcmp_creacionfecha as fecha ,TO_CHAR(cc.mcmp_valor, 'FM999999999.##') as estadoInicial ,null as estadoFinal ,'COMPROBANTE' as estado ,null as usuario ,null as responsable ,null as responsableImagen ,cc.ccmp_codigo as modificadorNombre ,cc.ccmp_concepto as comentario ,null as plantilla ,null as plantillaNombre ,null as nombre ,TO_CHAR(cc.dcmp_fechaanulacion, 'YYYY/MM/DD HH24:MI') as transaccion ,null as adjunto from account.comprobante_cmp cc where cc.ccmp_documento = #{dto.documentoPrincipal}
order by fecha desc LIMIT #{dto.paginacionRegistroFinal} OFFSET #{dto.paginacionRegistroInicial}
